<script setup>
import { Money3Directive } from 'v-money3'
import { mxnMask, decimalMask } from '../../config/numberMasks'
const vMoney3 = Money3Directive
import {ref,computed,onMounted,watch} from 'vue'
import {useRouter,useRoute} from 'vue-router'
import Swal from 'sweetalert2'
import {confirmAction as confirmAdminAction} from '../../utils/adminAlerts'
import {api,post,put,remove} from '../../services/api'
const router=useRouter(),route=useRoute()
// ANDARMA_V36_INVENTORY
const rows=ref([]),devs=ref([]),q=ref(''),dev=ref(String(route.query.desarrollo||'')),status=ref(''),mapped=ref(''),page=ref(1),last=ref(1),total=ref(0)
const loading=ref(false),saving=ref(false),modal=ref(false),editing=ref(null)
const empty=()=>({development_id:'',code:'',block:'',area_m2:'',front_m:'',depth_m:'',price:'',status:'available',description:''})
const form=ref(empty())
const statusLabels={available:'Disponible',reserved:'Apartado',sold:'Vendido',inactive:'Inactivo'}
const fmt=x=>new Intl.NumberFormat('es-MX',{style:'currency',currency:'MXN',maximumFractionDigits:0}).format(Number(x||0))
const alertBase={customClass:{popup:'andarma-swal',title:'andarma-swal__title',htmlContainer:'andarma-swal__text',actions:'andarma-swal__actions',confirmButton:'andarma-swal__confirm',cancelButton:'andarma-swal__cancel'},buttonsStyling:false}
function err(e){Swal.fire({...alertBase,icon:'error',title:'No se pudo realizar la operación',text:e.message||'Ocurrió un error'})}
function success(s){Swal.fire({...alertBase,toast:true,position:'top-end',timer:2400,showConfirmButton:false,icon:'success',title:s})}
async function confirmDelete(){return confirmAdminAction({title:'Eliminar terreno',text:'Solo se puede eliminar si no tiene comprador, pagos ni ubicación mapeada.',confirmText:'Sí, eliminar',cancelText:'Conservar',variant:'danger'})}
async function load(){loading.value=true;try{const p=new URLSearchParams({page:page.value,per_page:20});if(q.value)p.set('q',q.value);if(dev.value)p.set('development_id',dev.value);if(status.value)p.set('status',status.value);if(mapped.value)p.set('mapped',mapped.value);const r=await api('/admin/im/inventory?'+p);rows.value=r.data||[];last.value=r.last_page||1;total.value=r.total||0}catch(e){err(e)}finally{loading.value=false}}
async function loadDevs(){try{devs.value=(await api('/admin/im/developments')).data||[]}catch(e){err(e)}}
let t;watch([q,dev,status,mapped],()=>{page.value=1;clearTimeout(t);t=setTimeout(load,250)})
function newLot(){editing.value=null;form.value=empty();form.value.development_id=dev.value||devs.value[0]?.id||'';modal.value=true}
function editLot(row){editing.value=row;form.value={development_id:row.development_id,code:row.code||'',block:row.block||'',area_m2:row.area_m2??'',front_m:row.front_m??'',depth_m:row.depth_m??'',price:row.price??'',status:row.status,description:row.description||''};modal.value=true}
async function save(){if(saving.value)return;if(!form.value.development_id||!form.value.code.trim()){return err(new Error('Selecciona un desarrollo y captura un número de lote.'))}saving.value=true;try{const data={...form.value,development_id:Number(form.value.development_id)};['area_m2','front_m','depth_m','price'].forEach(k=>{data[k]=data[k]===''?null:Number(data[k])});if(editing.value)await put('/admin/im/inventory/'+editing.value.id,data);else await post('/admin/im/inventory',data);modal.value=false;success(editing.value?'Terreno actualizado':'Terreno creado');await load()}catch(e){err(e)}finally{saving.value=false}}
async function del(row){if(!await confirmDelete())return;try{await remove('/admin/im/inventory/'+row.id);success('Terreno eliminado');await load()}catch(e){err(e)}}
// ANDARMA_V40_WHATSAPP
function whatsappLink(row){
  if(!['yellow','red'].includes(row.payment_tone))return ''
  let phone=String(row.buyer_phone||'').replace(/\D/g,'')
  if(phone.length===10)phone='52'+phone
  else if(phone.length===13&&phone.startsWith('521'))phone='52'+phone.slice(3)
  if(!/^\d{11,15}$/.test(phone))return ''
  const name=String(row.buyer_name||'').trim()
  const property=[row.block,row.code].filter(Boolean).join(' · ')
  const message=`Hola${name?' '+name:''}, te contactamos de ANDARMA para dar seguimiento al estado de cuenta de tu terreno ${property} en ${row.development_name||'nuestro desarrollo'}. ¿Podemos apoyarte a revisar tus pagos?`
  return `https://wa.me/${phone}?text=${encodeURIComponent(message)}`
}
function seeMap(row){if(row.mapped_plan_id)router.push('/admin/mapas/'+row.mapped_plan_id+'?lote='+row.id)}
onMounted(async()=>{await loadDevs();await load()})
</script>
<template>
<section class="ad-module space-y-5">
  <header class="flex flex-wrap items-start justify-between gap-4"><div><span class="ad-kicker">GESTIÓN INMOBILIARIA / INVENTARIO</span><h1 class="ad-heading">Propiedades</h1><p class="ad-muted">Terrenos históricos y nuevos en un mismo listado, tengan plano o no.</p></div><div class="flex flex-wrap gap-2"><button class="ad-btn" @click="router.push('/admin/mapas')"><i class="fa-solid fa-map"></i> Mapas</button><button v-can="'properties.create'" class="ad-btn ad-btn--primary" @click="newLot"><i class="fa-solid fa-plus"></i> Nuevo terreno</button></div></header>
  <div class="ad-card"><div class="flex flex-wrap items-end gap-3"><label class="ad-label grow min-w-48">Buscar<input v-model="q" class="ad-input" placeholder="Lote, manzana o desarrollo"/></label><label class="ad-label grow min-w-40">Desarrollo<select v-model="dev" class="ad-select"><option value="">Todos</option><option v-for="d in devs" :key="d.id" :value="d.id">{{d.name}}</option></select></label><label class="ad-label grow min-w-36">Estado<select v-model="status" class="ad-select"><option value="">Todos</option><option v-for="(label,k) in statusLabels" :key="k" :value="k">{{label}}</option></select></label><label class="ad-label grow min-w-36">Plano<select v-model="mapped" class="ad-select"><option value="">Todos</option><option value="yes">Con mapa</option><option value="no">Sin mapa</option></select></label><button class="ad-btn" @click="load"><i class="fa-solid fa-rotate"></i> Actualizar</button></div></div>
  <div class="ad-card"><div class="flex items-center justify-between gap-3 mb-3"><h2 class="font-bold text-base">Inventario general</h2><span class="ad-badge">{{total}} registros</span></div><div class="ad-table-wrap"><table class="ad-table"><thead><tr><th>Propiedad</th><th>Desarrollo</th><th>Superficie</th><th>Precio</th><th>Estado</th><th>Cobranza</th><th>Plano</th><th>Acciones</th></tr></thead><tbody><tr v-for="r in rows" :key="r.id"><td><strong>{{r.block ? r.block+' · ' : ''}}{{r.code}}</strong></td><td>{{r.development_name}}</td><td>{{r.area_m2||'—'}} m²</td><td>{{fmt(r.price)}}</td><td><span class="ad-badge" :class="r.status==='available'?'ad-badge--success':r.status==='sold'?'ad-badge--danger':''">{{statusLabels[r.status]||r.status}}</span></td><td><span class="ad-cobranza-badge" :class="'ad-cobranza-badge--'+(r.payment_tone||'neutral')"><i class="fa-solid fa-circle" aria-hidden="true"></i> {{r.payment_label||'No aplica'}}</span></td><td><button v-if="r.mapped_plan_id" class="ad-btn" @click="seeMap(r)"><i class="fa-solid fa-location-dot"></i> Ver mapa</button><span v-else class="ad-muted">Sin mapa</span></td><td><div class="ad-actions"><a v-if="whatsappLink(r)" class="ad-btn ad-btn--whatsapp" :href="whatsappLink(r)" target="_blank" rel="noopener noreferrer" :aria-label="'Contactar por WhatsApp a '+(r.buyer_name||'comprador')" title="Abrir conversación de WhatsApp"><i class="fa-brands fa-whatsapp" aria-hidden="true"></i> WhatsApp</a><button v-can="'properties.edit'" class="ad-btn" @click="editLot(r)"><i class="fa-solid fa-pen"></i> Editar</button><button v-can="'properties.delete'" class="ad-btn ad-btn--danger" @click="del(r)"><i class="fa-solid fa-trash"></i> Eliminar</button></div></td></tr><tr v-if="!rows.length&&!loading"><td colspan="8" class="text-center py-10">No hay terrenos con esos filtros.</td></tr></tbody></table></div><div class="flex justify-between items-center pt-4"><span class="ad-muted">Página {{page}} de {{last}}</span><div class="flex gap-2"><button class="ad-btn" :disabled="page<=1" @click="page--;load()">Anterior</button><button class="ad-btn" :disabled="page>=last" @click="page++;load()">Siguiente</button></div></div></div>
  <div v-if="modal" class="ad-modal-backdrop" @click.self="modal=false"><section class="ad-modal" role="dialog" aria-modal="true" aria-label="Formulario de terreno"><header class="ad-modal__header"><div><span class="ad-kicker">PROPIEDADES</span><h2 class="ad-modal-title">{{editing?'Editar terreno':'Nuevo terreno'}}</h2><p class="ad-muted">La ubicación visual es opcional y se asigna desde Mapas.</p></div><button class="ad-icon-btn" aria-label="Cerrar" @click="modal=false"><i class="fa-solid fa-xmark"></i></button></header><form @submit.prevent="save" class="flex flex-col min-h-0"><div class="ad-modal__body space-y-4"><div class="ad-form-grid"><label class="ad-label ad-form-span">Desarrollo *<select v-model="form.development_id" required class="ad-select"><option value="">Seleccionar</option><option v-for="d in devs" :key="d.id" :value="d.id">{{d.name}}</option></select></label><label class="ad-label">Manzana (opcional)<input v-model.trim="form.block" maxlength="120" class="ad-input" placeholder="Ej. M5"/></label><label class="ad-label">Número de lote *<input v-model.trim="form.code" required maxlength="255" class="ad-input" placeholder="Ej. L01"/></label><label class="ad-label">Superficie (m²)<input v-model.lazy="form.area_m2" v-money3="decimalMask" type="text" inputmode="decimal" autocomplete="off" class="ad-input"/></label><label class="ad-label">Precio (MXN)<input v-model.lazy="form.price" v-money3="mxnMask" type="text" inputmode="decimal" autocomplete="off" class="ad-input"/></label><label class="ad-label">Frente (m)<input v-model.lazy="form.front_m" v-money3="decimalMask" type="text" inputmode="decimal" autocomplete="off" class="ad-input"/></label><label class="ad-label">Fondo (m)<input v-model.lazy="form.depth_m" v-money3="decimalMask" type="text" inputmode="decimal" autocomplete="off" class="ad-input"/></label><label class="ad-label ad-form-span">Disponibilidad<select v-model="form.status" class="ad-select"><option v-for="(label,k) in statusLabels" :key="k" :value="k">{{label}}</option></select></label><label class="ad-label ad-form-span">Observaciones<textarea v-model="form.description" maxlength="5000" class="ad-textarea" rows="3" placeholder="Características u observaciones"></textarea></label></div><p class="ad-hint"><i class="fa-solid fa-circle-info"></i> El comprador y los pagos se administran por separado. No debes cargar una imagen por lote.</p></div><footer class="ad-modal__footer"><button type="button" class="ad-btn" @click="modal=false">Cancelar</button><button type="submit" class="ad-btn ad-btn--primary" :disabled="saving"><i class="fa-solid fa-floppy-disk"></i> {{saving?'Guardando...':'Guardar terreno'}}</button></footer></form></section></div>
</section>
</template>
